const r=2**30;export const deep=(g,d)=>{if(d>=r)return g;const w=[];let t=g,v;for(;;){if(typeof t==="object"){if(t.next===undefined){const f=t.shift();t.push(r);t=f.apply(null,t);continue}const n=t.next(v);v=n.value;if(typeof v==="object"){if(!n.done)w.push(t);t=v;continue}}else v=t;if(w.length===0)return v;t=w.pop()}};export const listEq=(m,x,y,d)=>{if(d>=r)return s(m,x,y,true);let a=x,b=y;while(a.$===1&&b.$===1){if(!m(a.a,b.a,d))return false;a=a.b;b=b.b}return a.$===b.$};export const listCompare=(m,x,y,d)=>{if(d>=r)return s(m,x,y,false);let a=x,b=y;while(a.$===1&&b.$===1){const o=m(a.a,b.a,d);if(o!=="EQ")return o;a=a.b;b=b.b}return a.$===b.$?"EQ":a.$===0?"LT":"GT"};const s=function*(m,a,b,e){while(a.$===1&&b.$===1){let o=m(a.a,b.a,r);if(typeof o==="object")o=yield o;if(e?!o:o!=="EQ")return o;a=a.b;b=b.b}return e?a.$===b.$:a.$===b.$?"EQ":a.$===0?"LT":"GT"};
